42	  if (!session || !idle || session.phase !== 'flying') return;
43	  const now = performance.now();
44	  const st = idle.tick(now);
45	  if (st === 'ok') idleShow('');
46	  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
47	  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
