50	function idleStart(): void {
51	  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
52	  const [a, b] = idleParams();
53	  idle = new ExIdle(a, b); idle.reset(performance.now());
54	  idleShown = '';
55	  idleTimer = window.setInterval(idleTick, M.idleTickMs);
56	  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
57	}
